{
  "name": "@oligarchy/async",
  "private": true,
  "type": "module",
  "exports": {
    ".": "./src/main.ts"
  },
  "scripts": {
    "check:types": "tsc --noEmit -p tsconfig.json",
    "test:unit": "bun --bun vitest run"
  },
  "dependencies": {
    "jarl": "catalog:"
